package utb.fai;


import java.net.URI;
import java.util.HashSet;
import java.util.LinkedList;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;


public class App {

	public static void main(String[] args) {
		LinkedList<URIinfo> foundURIs = new LinkedList<URIinfo>();
		HashSet<URI> visitedURIs = new HashSet<URI>();
		URI uri;
		try {

			if (args.length < 1) {
				System.err.println("Missing parameter - start URL");
				return;
			}

			HttpClient client = HttpClient.newBuilder()
				.followRedirects(HttpClient.Redirect.NORMAL)
				.build();

			uri = new URI(args[0]);
			foundURIs.add(new URIinfo(uri, 0));
			visitedURIs.add(uri);

			/**
			 * Zde zpracujte dalí parametry - maxDepth a debugLevel
			 */

			int maxDepth = 2;

			if (args.length >= 2) {
				maxDepth = Integer.parseInt(args[1]);
			}


			ParserCallback callBack = new ParserCallback(visitedURIs, foundURIs, maxDepth);

			while (!foundURIs.isEmpty()) {
				URIinfo URIinfo = foundURIs.removeFirst();
				callBack.depth = URIinfo.depth;
				callBack.pageURI = uri = URIinfo.uri;
				System.err.println("Analyzing " + uri);


				HttpRequest request = HttpRequest.newBuilder()
					.uri(uri)
					.build();

				HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

				if (response.statusCode() == 200) {
					String html = response.body();

					if (html != null) {
						Document doc = Jsoup.parse(html, uri.toString());
						callBack.parseDocument(doc);

						System.out.println("Title: " + doc.title());
					}
				} else {
					System.err.println("Error: " + response.statusCode());
				}

			}
		} catch (Exception e) {
			System.err.println("Unhandled error occured...");
			e.printStackTrace();
		}
	}

}
